#ifndef TINTA_APP_ICON_DATA_H
#define TINTA_APP_ICON_DATA_H

#include <cstddef>

// THE APPLICATION ICON'S BYTES, EMBEDDED ONCE FOR BOTH BACKENDS.
//
// The definition is GENERATED at configure time from resources/tinta.ico into
// ${CMAKE_BINARY_DIR}/generated/app_icon_data.cpp -- see the "embedded app icon" block in
// CMakeLists.txt. Only this declaration is checked in, so the 36 KB asset lives in exactly
// one place on disk and no generated file is in git.
//
// WHY A GENERATED BYTE ARRAY RATHER THAN A Qt .qrc, WHICH IS WHAT THE PLAN SAID. A .qrc is
// Qt-only. The Direct2D build would have kept reading the icon through
// LoadImageW(GetModuleHandleW(nullptr), L"IDI_ICON1", ...) against resources/tinta.rc, so
// the two backends would have had two different embedding mechanisms and the call site
// would have kept an #ifdef -- the guard RELOCATED rather than removed, which was the whole
// point of the slice. One array is read identically by both, so startPageEnsureIcon has no
// conditional compilation left in it at all.
//
// resources/tinta.rc HAS NO CONSUMER since 2026-10-07 and is kept anyway. Its one reader was
// main_d2d.cpp's WNDCLASSEX::hIcon, an HICON from LoadIconW, and main_d2d.cpp was deleted with
// the Direct2D stack. It stays because the Windows file association names the EXECUTABLE's
// icon resource (`qinta.exe,0`), which only a linked .rc provides and qinta.exe does not carry
// yet -- so the file is the starting point for that, not a leftover. It is linked into nothing.
//
// The array is the .ico CONTAINER, not decoded pixels -- 4 frames at 256/48/32/16. Decode it
// through tinta::decodeIconBytesToBitmap, which owns the frame-selection policy; picking a
// frame at a call site would put that policy in two places.

namespace tinta {

extern const unsigned char kAppIconIco[];
extern const size_t kAppIconIcoSize;

}  // namespace tinta

#endif  // TINTA_APP_ICON_DATA_H
